import json
import numpy as np
import pandas as pd

df = pd.DataFrame(DATA)
for f in ['DEPTH','MATRIX_LR','WEIGHT_DECAY']:
    df[f] = df['config'].apply(lambda c: c[f])

results = {'main_effects': {}, 'best_config': None, 'n': len(df)}
for f in ['DEPTH','MATRIX_LR','WEIGHT_DECAY']:
    grp = df.groupby(f)['outcome'].agg(['mean','count']).to_dict('index')
    results['main_effects'][f] = {k: {'mean': round(v['mean'],4), 'n': int(v['count'])} for k,v in grp.items()}

best_idx = df['outcome'].idxmax()
results['best_config'] = {'config': df.loc[best_idx, 'config'], 'outcome': df.loc[best_idx, 'outcome']}
print(json.dumps(results, indent=2))

