import json
import numpy as np

depth_outcomes = {}
for d in DATA:
    depth = d['config']['DEPTH']
    depth_outcomes.setdefault(depth, []).append(d['outcome'])

means = {k: np.mean(v) for k, v in depth_outcomes.items()}
counts = {k: len(v) for k, v in depth_outcomes.items()}

depth8_mean = means.get('8', 0)
best_other = max(v for k, v in means.items() if k != '8')

result = {
    'means': means,
    'counts': counts,
    'depth8_advantage': depth8_mean - best_other,
    'accepted': depth8_mean > best_other and counts.get('8', 0) >= 3
}
print(json.dumps(result))

